class BST:
    def __init__(self):
        self.root = None
    def insert(self, val):
        if not self.root:
            self.root = BSTNode(val)
            return
        cur = self.root
        while True:
            if val < cur.val:
                if cur.left is None:
                    cur.left = BSTNode(val); break
                cur = cur.left
            else:
                if cur.right is None:
                    cur.right = BSTNode(val); break
                cur = cur.right
    def inorder(self):
        result = []
        def _inorder(node):
            if node:
                _inorder(node.left)
                result.append(node.val)
                _inorder(node.right)
        _inorder(self.root)
        return result

