def take(n, iterable):
    result = []
    for i, x in enumerate(iterable):
        if i >= n: break
        result.append(x)
    return result

def drop(n, iterable):
    result = []
    for i, x in enumerate(iterable):
        if i >= n:
            result.append(x)
    return result

from collections import defaultdict

def group_by(lst, key_func):
    result = defaultdict(list)
    for item in lst:
        result[key_func(item)].append(item)
    return dict(result)

