def pipe(*funcs):
    def wrapper(x):
        for f in funcs:
            x = f(x)
        return x
    return wrapper

def curry(func):
    def curried(*args):
        if len(args) >= func.__code__.co_argcount:
            return func(*args)
        return lambda *more: curried(*(args + more))
    return curried

def partial(func, *args):
    def wrapper(*more):
        return func(*(args + more))
    return wrapper

def fib_gen(n):
    a, b = 0, 1
    for _ in range(n):
        yield a
        a, b = b, a + b

def prime_gen(n):
    for num in range(2, n+1):
        if all(num % i != 0 for i in range(2, int(num**0.5)+1)):
            yield num

def even_gen(n):
    for x in range(0, n, 2):
        yield x

