def factorial(n):
    if n <= 1: return 1
    return n * factorial(n-1)

def fib(n):
    if n <= 1: return n
    return fib(n-1) + fib(n-2)

def power(base, exp):
    if exp == 0: return 1
    if exp % 2 == 0:
        half = power(base, exp // 2)
        return half * half
    return base * power(base, exp - 1)

def gcd(a, b):
    if b == 0: return a
    return gcd(b, a % b)

def sum_list(lst):
